import { useState, useEffect } from "react";
import {
  TextField,
  Button,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Box,
  Typography,
} from "@mui/material";
import classes from "./OperatorDestination.module.css";

function OperatorDestinationForm({ assignment, onSubmit, onCancel }) {
  const [formData, setFormData] = useState({
    userId: assignment?.userId || "",
    destinationId: assignment?.destinationId || "",
  });
  const [users, setUsers] = useState([]);
  const [destinations, setDestinations] = useState([]);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    fetchUsers();
    fetchDestinations();
  }, []);

  useEffect(() => {
    if (assignment) {
      setFormData({
        userId: assignment.userId || "",
        destinationId: assignment.destinationId || "",
      });
    }
  }, [assignment]);

  const fetchUsers = async () => {
    const token = localStorage.getItem("token");
    try {
      const res = await fetch("http://localhost:3000/dest/api/v1/users", {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setUsers(data);
      }
    } catch (err) {
      console.error("Failed to fetch users:", err);
    }
  };

  const fetchDestinations = async () => {
    const token = localStorage.getItem("token");
    try {
      const res = await fetch(
        "http://localhost:3000/dest/api/v1/destinations",
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      if (res.ok) {
        const data = await res.json();
        setDestinations(data);
      }
    } catch (err) {
      console.error("Failed to fetch destinations:", err);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: parseInt(value) }));
    if (errors[name]) setErrors((prev) => ({ ...prev, [name]: null }));
  };

  const validate = () => {
    const newErrors = {};
    if (!formData.userId) newErrors.userId = "User is required";
    if (!formData.destinationId)
      newErrors.destinationId = "Destination is required";
    return newErrors;
  };

  const handleFormSubmit = (e) => {
    e.preventDefault();
    const validationErrors = validate();
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    const submitData = {
      userId: formData.userId,
      destinationId: formData.destinationId,
    };

    onSubmit(submitData);
  };

  return (
    <form
      className={classes.operatorDestinationForm}
      onSubmit={handleFormSubmit}
    >
      <FormControl fullWidth margin="normal" error={!!errors.userId}>
        <InputLabel>User</InputLabel>
        <Select name="userId" value={formData.userId} onChange={handleChange}>
          <MenuItem value="">Select User</MenuItem>
          {users.map((user) => (
            <MenuItem key={user.userId} value={user.userId}>
              {user.name}
            </MenuItem>
          ))}
        </Select>
        {errors.userId && (
          <Typography color="error">{errors.userId}</Typography>
        )}
      </FormControl>
      <FormControl fullWidth margin="normal" error={!!errors.destinationId}>
        <InputLabel>Destination</InputLabel>
        <Select
          name="destinationId"
          value={formData.destinationId}
          onChange={handleChange}
        >
          <MenuItem value="">Select Destination</MenuItem>
          {destinations.map((dest) => (
            <MenuItem key={dest.destination_id} value={dest.destination_id}>
              {dest.name}
            </MenuItem>
          ))}
        </Select>
        {errors.destinationId && (
          <Typography color="error">{errors.destinationId}</Typography>
        )}
      </FormControl>
      <div className={classes.formActions}>
        <Button type="submit" variant="contained" color="primary">
          {assignment ? "Update" : "Create"} Assignment
        </Button>
        <Button variant="outlined" onClick={onCancel}>
          Cancel
        </Button>
      </div>
    </form>
  );
}

export default OperatorDestinationForm;
